import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`solar-proposal`,heroTitle:`Build winning solar proposals in minutes`,heroSubtitle:`Perplexity Computer analyzes your uploaded site package and utility data, sizes the right system, and drafts a customer-ready solar proposal automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your solar site package`,inputFileAccept:`.pdf,.doc,.docx,.csv,.xlsx,.xls,.png,.jpg,.jpeg`,inputFilePrefill:`I've uploaded utility bills, site photos, roof notes, or a survey package. Build a complete solar proposal. (1) Extract energy usage, roof geometry, shading, electrical service details, storage interest, financing preferences, and installation constraints from the uploaded files. (2) Recommend the right system size, panel and inverter package, production assumptions, labor, and optional storage scope. (3) Build pricing options with assumptions, financing or cash alternatives, incentives, and margin. (4) Highlight exclusions, interconnection questions, and site-verification items that should be confirmed before sending. (5) Deliver a polished solar proposal with system summary, pricing, savings narrative, and next steps that is ready for the customer.`,heroOverlaySteps:[`Extracting usage, roof geometry, shading, and install constraints from your files`,`Sizing the right system, equipment package, and optional storage scope`,`Building pricing options with assumptions, incentives, and financing alternatives`,`Customer-ready solar proposal with savings narrative, ready to send`],generatingSteps:[`Reading the uploaded utility bills, site photos, and survey package`,`Designing an agent to organize system sizing, production assumptions, and pricing`,`Configuring proposal logic for incentives, financing options, and margin`,`Preparing a polished solar proposal with pricing, savings story, and next steps`],featureSectionTitle:`From site package to proposal-ready pricing`,featureCardTitles:[`Connects to your sales workflow`,`Proposals built around fit, savings, and close rate`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Bills, photos, surveys, and internal planning workflows stay connected so scoping and follow-up move faster.`,`System sizing. Equipment options. Financing choices. Savings narrative. Computer gives your team a solar proposal draft that is ready for customer review.`],capabilitySectionTitle:`Your proposal desk, on autopilot`,capabilitySectionSubtitle:`Upload the site package, get back a solar proposal built around the real property and usage profile.`,capabilityCards:[{title:`Site & Usage Analysis`,description:`Computer can extract energy usage, roof geometry, shading, electrical service details, and installation constraints from bills and site files.`},{title:`System Design & Pricing`,description:`Computer can recommend the right system size, equipment package, storage options, and labor assumptions for the property.`},{title:`Proposal Builder`,description:`Computer can build pricing with incentives, financing alternatives, savings assumptions, and margin so the proposal is clearer and easier to close.`},{title:`Connect Your Tools`,description:`Computer can organize proposal drafts across docs, sheets, and internal workflows so review and handoff are easy for your team.`},{title:`Knows Your Packages`,description:`Computer can remember your preferred equipment bundles, pricing guardrails, and proposal structure across sessions so every draft stays consistent.`},{title:`Follow-Up Support`,description:`Computer can prepare customer summaries and next-step notes so your team can move from proposal to site visit or close faster.`}]});export{t as default};
